package local.tvmorph.visualcheck;
import android.app.*;import android.content.*;import android.os.*;import android.view.View;import android.webkit.WebView;import java.lang.reflect.*;import java.util.concurrent.*;
/** QA only: first render and return to an existing Home, without altering user data. */
public class LauncherVisualPerformanceInstrumentation extends Instrumentation {
 @Override public void onCreate(Bundle args){super.onCreate(args);start();}
 String evaluate(WebView web,String script)throws Exception{CountDownLatch done=new CountDownLatch(1);String[] value={null};runOnMainSync(()->web.evaluateJavascript(script,r->{value[0]=r;done.countDown();}));if(!done.await(8,TimeUnit.SECONDS))throw new AssertionError("WebView did not respond within eight seconds");return value[0];}
 @Override public void onStart(){Bundle result=new Bundle();try{
  long begin=SystemClock.elapsedRealtime();Activity home=startActivitySync(new Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_LEANBACK_LAUNCHER).setClassName("local.tvmorph.tv","local.tvmorph.tv.TvActivity").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));
  Field f=home.getClass().getDeclaredField("web");f.setAccessible(true);WebView web=(WebView)f.get(home);Field c=home.getClass().getDeclaredField("startupCover");c.setAccessible(true);View cover=(View)c.get(home);
  boolean ready=false;for(int i=0;i<80&&!ready;i++){ready="true".equals(evaluate(web,"!!window.ReferencePreview&&!document.documentElement.classList.contains('theme-starting')"));if(!ready)Thread.sleep(100);}
  if(!ready)throw new AssertionError("Launcher did not reach ready Home");Thread.sleep(1000);long cold=SystemClock.elapsedRealtime()-begin;
  for(int i=0;i<60&&cover.getVisibility()!=View.GONE;i++)Thread.sleep(100);
  if(cover.getVisibility()!=View.GONE)throw new AssertionError("Startup cover remains on usable Home");
  String cleanSurfaces=evaluate(web,"(function(){document.querySelector('.reference-card').focus();return Array.from(document.querySelectorAll('#morph-header nav button,#weather-card,#view-home .home-tools>button')).filter(function(n){return !n.hidden&&n.offsetWidth;}).every(function(n){var s=getComputedStyle(n);return s.backgroundImage==='none'&&s.borderTopColor==='rgba(0, 0, 0, 0)';});})()");
  if(!"true".equals(cleanSurfaces))throw new AssertionError("Idle menu buttons must not have added card surfaces");result.putString("idleSurfaces","transparent, no extra button cards");
  String dockCentered=evaluate(web,"Array.from(document.querySelectorAll('#favourites>button')).every(function(n){var a=n.querySelector('.app-icon,.plus-icon'),b=n.querySelector('.app-name');if(!a||!b)return true;a=a.getBoundingClientRect();b=b.getBoundingClientRect();return Math.abs(a.left+a.width/2-b.left-b.width/2)<1;})");
  if(!"true".equals(dockCentered))throw new AssertionError("Dock text is not centered below icon");result.putString("dockAlignment","centered within one pixel");
  evaluate(web,"(function(){window.__navAudit=null;var frames=[],handlers=[],mutations=0,previous=performance.now(),running=true;var mo=new MutationObserver(function(records){mutations+=records.length;});mo.observe(document.body,{subtree:true,childList:true,attributes:true});function frame(now){frames.push(now-previous);previous=now;if(running)requestAnimationFrame(frame);}requestAnimationFrame(frame);var targets=Array.from(document.querySelectorAll('#morph-header nav button')).filter(function(n){return !n.hidden&&n.offsetWidth;});var index=0;function step(){if(index===32){running=false;mo.disconnect();function stats(a){a.sort(function(x,y){return x-y;});return {median:a[Math.floor(a.length*.5)],p95:a[Math.floor(a.length*.95)],max:a[a.length-1]};}window.__navAudit={frames:stats(frames),handlers:stats(handlers),mutations:mutations,focused:document.activeElement.id,targets:targets.map(function(n){return n.id;}),mode:ClearTV.Performance.get(),startupAccordion:!!document.querySelector('.reference-startup-options'),stripes:getComputedStyle(document.body,'::after').display};return;}var at=performance.now();targets[index%targets.length].focus();document.dispatchEvent(new KeyboardEvent('keydown',{key:'ArrowRight',keyCode:39,which:39,bubbles:true}));handlers.push(performance.now()-at);index++;setTimeout(step,100);}step();})()");
  String audit="null";for(int i=0;i<150&&"null".equals(audit);i++){Thread.sleep(100);audit=evaluate(web,"window.__navAudit||null");}result.putString("navigationAudit",audit);
  evaluate(web,"(function(){window.__dockAudit=null;var frames=[],handlers=[],mutations=0,previous=performance.now(),running=true;var mo=new MutationObserver(function(records){mutations+=records.length;});mo.observe(document.body,{subtree:true,childList:true,attributes:true});function frame(now){frames.push(now-previous);previous=now;if(running)requestAnimationFrame(frame);}requestAnimationFrame(frame);var targets=Array.from(document.querySelectorAll('#favourites>button')).filter(function(n){return !n.hidden&&n.offsetWidth;});var index=0;function step(){if(index===32){running=false;mo.disconnect();function stats(a){a.sort(function(x,y){return x-y;});return {median:a[Math.floor(a.length*.5)],p95:a[Math.floor(a.length*.95)],max:a[a.length-1]};}window.__dockAudit={frames:stats(frames),handlers:stats(handlers),mutations:mutations,focused:document.activeElement.id,targets:targets.map(function(n){return n.id;}),mode:ClearTV.Performance.get(),startupAccordion:!!document.querySelector('.reference-startup-options'),stripes:getComputedStyle(document.body,'::after').display};return;}var at=performance.now();targets[index%targets.length].focus();document.dispatchEvent(new KeyboardEvent('keydown',{key:'ArrowRight',keyCode:39,which:39,bubbles:true}));handlers.push(performance.now()-at);index++;setTimeout(step,100);}step();})()");
  String dockAudit="null";for(int i=0;i<150&&"null".equals(dockAudit);i++){Thread.sleep(100);dockAudit=evaluate(web,"window.__dockAudit||null");}result.putString("dockAudit",dockAudit);
  evaluate(web,"TVNative.startup()");Thread.sleep(300);
  String nativeStartup=evaluate(web,"!document.getElementById('view-settings').hidden&&document.getElementById('setting-startup').getAttribute('aria-expanded')==='true'");
  if(!"true".equals(nativeStartup))throw new AssertionError("Native startup entry did not use inline launcher settings");result.putString("nativeStartup","inline shared Settings");
  String startup=evaluate(web,"(function(){var b=document.getElementById('setting-startup');b.click();b.click();var opened=b.getAttribute('aria-expanded')==='true'&&b.nextElementSibling.querySelectorAll('button').length===4;b.click();var closed=b.getAttribute('aria-expanded')==='false';ClearTV.showView('home');return opened&&closed;})()");
  if(!"true".equals(startup))throw new AssertionError("Native launcher options must expand/collapse inside Settings: "+startup);
  for(String childName:new String[]{"RadioActivity","BridgeReceiverActivity","IptvActivity"}){
   ActivityMonitor monitor=addMonitor("local.tvmorph.tv."+childName,null,false);runOnMainSync(()->home.startActivity(new Intent().setClassName("local.tvmorph.tv","local.tvmorph.tv."+childName)));Activity child=monitor.waitForActivityWithTimeout(10000);removeMonitor(monitor);if(child==null)throw new AssertionError(childName+" did not open");Thread.sleep(500);long back=SystemClock.elapsedRealtime();runOnMainSync(()->child.finish());waitForIdleSync();
   for(int i=0;i<10;i++){if(cover.getVisibility()!=View.GONE)throw new AssertionError("Loading cover returned after "+childName);Thread.sleep(50);}
   if(!"true".equals(evaluate(web,"!!window.ReferencePreview&&!document.getElementById('view-home').hidden")))throw new AssertionError("Home lost after "+childName);
   result.putLong(childName+"ReturnMs",SystemClock.elapsedRealtime()-back);
  }
  result.putLong("coldReadyMs",cold);result.putString("result","PASS: Android Home reaches ready; returning from Radio, Bridge and IPTV preserves Home without showing startup cover. No screenshots or settings saved.");finish(Activity.RESULT_OK,result);
 }catch(Throwable error){result.putString("error",android.util.Log.getStackTraceString(error));finish(Activity.RESULT_CANCELED,result);}}
}
